import{_ as t,o,c as a,a0 as n}from"./chunks/framework.BL79I5mR.js";const m=JSON.parse('{"title":"Anderson acceleration of the Picard loop (ANDERSON_ACCEL)","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/engine-modifications/03-anderson-acceleration.md","filePath":"explanation/engine-modifications/03-anderson-acceleration.md"}'),r={name:"explanation/engine-modifications/03-anderson-acceleration.md"};function i(d,e,s,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="anderson-acceleration-of-the-picard-loop-anderson-accel" tabindex="-1">Anderson acceleration of the Picard loop (<code>ANDERSON_ACCEL</code>) <a class="header-anchor" href="#anderson-acceleration-of-the-picard-loop-anderson-accel" aria-label="Permalink to &quot;Anderson acceleration of the Picard loop (`ANDERSON_ACCEL`)&quot;">​</a></h1><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>The dynamic wave solver solves the node and link equations by <em>functional iteration</em> (Picard / successive approximations): each pass applies the same head update operator $G$ to the latest head estimates until no node changes by more than the head tolerance $\\varepsilon_H$. The fixed-point iteration converges <em>linearly</em>, and the subrelaxation factor $\\omega = 0.5$ that damps each update stabilizes the iteration without improving its rate. In networks with many strongly coupled nodes, the solver can exhaust its 8 attempts (<code>MAX_TRIALS</code>) in almost every routing step, even under smooth conditions.</p><h2 id="the-method" tabindex="-1">The method <a class="header-anchor" href="#the-method" aria-label="Permalink to &quot;The method&quot;">​</a></h2><p>Anderson acceleration of depth 2 (equivalent to Aitken&#39;s update) mixes the two most recent outputs of the operator. Let $H_k$ be the head estimate entering iteration $k$; the residual is</p><p>$$r_k = G(H_k) - H_k,$$</p><p>and the mixing coefficient is</p><p>$$\\alpha_k = \\mathrm{clamp}!\\left( \\frac{r_k,(r_k - r_{k-1})}{(r_k - r_{k-1})^{2}},\\ 0,\\ 1\\right), \\qquad H_{k+1} = (1-\\alpha_k),G(H_k) + \\alpha_k,G(H_{k-1}).$$</p><p>Clamping $\\alpha_k$ to $[0,1]$ restricts the update to an <em>interpolation</em> between two already computed and already bounded outputs of the operator; an extrapolated head is never produced. The mix is applied per node starting from the second attempt of each routing step.</p><h2 id="safeguards" tabindex="-1">Safeguards <a class="header-anchor" href="#safeguards" aria-label="Permalink to &quot;Safeguards&quot;">​</a></h2><ul><li><strong>Gate by residual magnitude</strong>: the mix is applied only when $\\lvert r_k \\rvert \\le 20,\\varepsilon_H$; far from the linear regime the mix could overshoot.</li><li><strong>Physical bounds</strong>: a negative mixed depth is discarded in favor of the ordinary Picard iteration.</li><li><strong>Exclusion of non-smooth nodes</strong>: the acceleration is skipped at nodes where the operator $G$ is known to be non-smooth (see the <a href="#safeguards">table of excluded nodes</a> below): surcharged nodes under <code>EXTRAN</code> with continuity <code>EXPLICIT</code> (the branch changes at the crown), active dynamic slot, conduits near the static slot cut, weirs or orifices at the crown, pump ends (discrete on/off state) and the ponding edge.</li><li><strong>Double convergence criterion</strong>: a node is counted as converged only when both the raw residual $\\lvert G(H_k) - H_k \\rvert$ and the accepted movement $\\lvert H_{k+1} - H_k \\rvert$ are within tolerance. Without this double condition, a mix landing close to the previous iteration could declare convergence while the flow balance remains unsatisfied.</li></ul><table tabindex="0"><thead><tr><th>Condition</th><th>When</th><th>Reason</th></tr></thead><tbody><tr><td>Surcharged node</td><td><code>SURCHARGE_METHOD EXTRAN</code> with <code>NODE_CONTINUITY EXPLICIT</code></td><td>the branch changes at the crown</td></tr><tr><td>Active dynamic slot</td><td><code>SURCHARGE_METHOD DYNAMIC_SLOT</code></td><td>the geometry is rewritten each iteration</td></tr><tr><td>Near static slot cut</td><td><code>SURCHARGE_METHOD SLOT</code>, $0.98 \\le \\bar y/y_{\\mathrm{full}} \\le 1.02$</td><td>the slot width enters abruptly</td></tr><tr><td>Weir/orifice at the crown</td><td>LGH upstream $\\ge$ crown</td><td>the discharge equation changes form</td></tr><tr><td>Pumps</td><td>both end nodes</td><td>the on/off state is discrete</td></tr><tr><td>Ponding edge</td><td>ponded node at $d_{\\mathrm{full}}$</td><td>$C^0$ floor at the ponding limit</td></tr></tbody></table><p><em>Table: Nodes excluded from Anderson acceleration.</em></p><p>The measured effect: reduction of attempt counts by roughly 25 to 50 % per routing step in networks that would otherwise iterate to the limit.</p>',14)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
